import copy

def merge(base: dict, overlay: dict) -> dict:
    def deep_copy(value):
        if isinstance(value, dict):
            return {k: deep_copy(v) for k, v in value.items()}
        if isinstance(value, list):
            return [deep_copy(v) for v in value]
        return value

    def recursive_merge(b, o):
        result = deep_copy(b)
        for k, ov in o.items():
            if k in result and isinstance(result[k], dict) and isinstance(ov, dict):
                result[k] = recursive_merge(result[k], deep_copy(ov))
            else:
                result[k] = deep_copy(ov)
