from collections import OrderedDict


class LRU:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)
```

**How it works:**

- **`OrderedDict`** preserves insertion order. Items at the front are least recently used; items at the back are most recently used.
- **`get(key)`**: If the key exists, `move_to_end` marks it as most recently used, then returns its value. Otherwise returns `None`.
- **`put(key, value)`**: If the key already exists, it's moved to the end (most recently used). The value is then set. If the cache exceeds capacity, `popitem(last=False)` removes the front item (the least recently used).
- **Validation**: `capacity < 1` raises `ValueError` at construction time.

import heapq


def order(deps):
    all_nodes = set(deps)

    for prereqs in deps.values():
        for node in prereqs:
            all_nodes.add(node)

    indegree = {node: 0 for node in all_nodes}
    graph = {node: [] for node in all_nodes}

    for node, prereqs in deps.items():
        for prereq in prereqs:
            graph[prereq].append(node)
            indegree[node] += 1

    ready = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)

    result = []
    processed = 0

    while ready:
        node = heapq.heappop(ready)
        result.append(node)
        processed += 1

        for dependent in graph[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if processed != len(all_nodes):
        raise ValueError("cycle detected")

    return result

